-- Importação (idempotente) dos itens de src/data/menuData.js pra products.
-- Reexecutar é seguro: o ON CONFLICT atualiza a linha existente pelo par
-- (company_id, slug). Atualizado em 2026-11-03 (correção 0.01 do cardápio
-- impresso). Itens removidos do cardápio são DESATIVADOS no fim do script
-- (is_active = false), não apagados.

on conflict (company_id, slug) where slug is not null do update set
  name        = excluded.name,
  category    = excluded.category,
  sale_price  = excluded.sale_price,
  is_active   = excluded.is_active,
  description = excluded.description,
  tags        = excluded.tags,
  is_featured = excluded.is_featured,
  sort_order  = excluded.sort_order,
  updated_at  = now();

-- Itens que saíram do cardápio (caipirinhas especiais, Baden Baden, Tamarindo/Pé na Cova, Havana Club, Malibu).
update public.products
   set is_active = false, updated_at = now()
 where company_id = '9467ade6-e25a-4aee-a6c8-03be31af4dda'
   and slug in ('cp4', 'cp5', 'cp6', 'cer7', 'shot4', 'shot9', 'shot10');
